<script>
  document.querySelectorAll('.portfolioFilter').forEach(button => button.addEventListener('click', () => {
    const filter = button.dataset.portfolioFilter; let visible = 0;
    document.querySelectorAll('.portfolioFilter').forEach(item => { item.classList.toggle('active', item === button); item.setAttribute('aria-selected', item === button ? 'true' : 'false'); });
    document.querySelectorAll('.portfolioCard').forEach(card => { const show = filter === 'all' || card.dataset.portfolioType === filter; card.hidden = !show; if (show) visible++; });
    document.querySelector('.portfolioEmpty').hidden = visible !== 0;
  }));
</script>
